import type { CartState } from '@/types/cart';

function renderCart(initialState: CartState) {
  return render(
    <CartProvider initialState={initialState}>
      <CartSummary />
    </CartProvider>
  );
}

describe('CartSummary', () => {
  it('renderiza corretamente com carrinho vazio', () => {
