      items: [
        { id: '1', name: 'Produto 1', price: 10, quantity: 2 },
        { id: '2', name: 'Produto 2', price: 20, quantity: 1 },
      ],
      couponCode: null,
    };
    renderCart(initialState);

    expect(screen.getByText('Produto 1 × 2')).toBeInTheDocument();
    expect(screen.getByText('Produto 2 × 1')).toBeInTheDocument();
    expect(screen.getByTestId('subtotal')).toHaveTextContent('R$ 40,00');
    expect(screen.getByTestId('total')).toHaveTextContent('R$ 40,00');
  });

