    const initialState: CartState = {
      items: [
        { id: '1', name: 'Produto 1', price: 100, quantity: 1 },
      ],
      couponCode: null,
    };
    const user = userEvent.setup();
    renderCart(initialState);

    await user.type(screen.getByLabelText('Cupom de desconto'), 'PROMO10');
    await user.click(screen.getByRole('button', { name: 'Aplicar' }));

    expect(screen.getByText('Cupom PROMO10 aplicado.')).toBeInTheDocument();
    expect(screen.getByTestId('discount')).toHaveTextContent('-R$ 10,00');
    expect(screen.getByTestId('total')).toHaveTextContent('R$ 90,00');
  });

  it('exibe erro ao aplicar cupom inválido', async () => {
    const initialState: CartState = {
      items: [
        { id: '1', name: 'Produto 1', price: 100, quantity: 1 },
      ],
      couponCode: null,
    };
    const user = userEvent.setup();
    renderCart(initialState);

    await user.type(screen.getByLabelText('Cupom de desconto'), 'INVALIDO');
    await user.click(screen.getByRole('button', { name: 'Aplicar' }));

    expect(screen.getByRole('alert')).toHaveTextContent('Cupom inválido.');
  });

  it('remove item do carrinho', async () => {
